    internal static int TgHtInit(emon.Port.Cells h, int n) {
        // An open-addressing table of (k1, k2, k3) -> value, room for n keys: 0 cap, 1 count, then 4
        // cells a slot (k1 k2 k3 value+1; 0 is empty).
