        int hcap = (n * 2) + 17;
        int i = 0;
        emon.Port.CellsPush(h, hcap);
        emon.Port.CellsPush(h, 0);
        while (i < (hcap * 4)) {
            emon.Port.CellsPush(h, 0);
            i += 1;
        }
        return hcap;
