    internal static int TgHtPut(emon.Port.Cells h, int k1, int k2, int k3, int v) {
        // Store v under the key; 1 when the key was already there (and nothing is stored), else 0.
        int hcap = emon.Port.CellsAt(h, 0);
        int s = TgHtSlot(k1, k2, k3, hcap);
        int at = 0;
        int guard = 0;
        while (guard < hcap) {
            at = 2 + (s * 4);
            if (emon.Port.CellsAt(h, at + 3) == 0) {
                emon.Port.CellsSet(h, at, k1);
                emon.Port.CellsSet(h, at + 1, k2);
                emon.Port.CellsSet(h, at + 2, k3);
                emon.Port.CellsSet(h, at + 3, v + 1);
                emon.Port.CellsSet(h, 1, emon.Port.CellsAt(h, 1) + 1);
                return 0;
            }
            if ((emon.Port.CellsAt(h, at) == k1) && (emon.Port.CellsAt(h, at + 1) == k2) && (emon.Port.CellsAt(h, at + 2) == k3)) {
                return 1;
