    internal static int TgHtGet(emon.Port.Cells h, int k1, int k2, int k3) {
        // The value under the key, -1 when absent.
        int hcap = emon.Port.CellsAt(h, 0);
        int s = TgHtSlot(k1, k2, k3, hcap);
        int at = 0;
        int guard = 0;
        while (guard < hcap) {
            at = 2 + (s * 4);
            if (emon.Port.CellsAt(h, at + 3) == 0) {
                return -1;
            }
            if ((emon.Port.CellsAt(h, at) == k1) && (emon.Port.CellsAt(h, at + 1) == k2) && (emon.Port.CellsAt(h, at + 2) == k3)) {
                return emon.Port.CellsAt(h, at + 3) - 1;
