        emon.Port.CellsSet(sc, at + ScKind, kind);
        emon.Port.CellsSet(sc, at + ScPage, page);
        emon.Port.CellsSet(sc, at + ScMcid, mcid);
        emon.Port.CellsSet(sc, at + ScStm, stm);
        emon.Port.CellsSet(sc, at + ScMark, -1);
        emon.Port.CellsSet(sc, at + ScGfirst, -1);
        emon.Port.CellsSet(sc, at + ScStmown, stmown);
        emon.Port.CellsSet(sc, at + ScFlags, fl);
        emon.Port.CellsSet(sc, at + ScBx0, 0);
