    internal static int TgOwner(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int d) {
        // An attribute object's owner: 0 none, 1 Layout, 2 List, 3 PrintField, 4 Table, 5 Hyperlink, 6 other.
        int o = TgDget(src, ar, dc, a, b, st, d, Pdfsnames.SnO());
        if (o == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, o) != 4) {
            return 6;
        }
        if (TgIs(ar, o, Pdfsnames.SnLayout()) == 1) {
            return 1;
        }
        if (TgIs(ar, o, Pdfsnames.SnList()) == 1) {
            return 2;
        }
        if (TgIs(ar, o, Pdfsnames.SnPrintField()) == 1) {
            return 3;
        }
        if (TgIs(ar, o, Pdfsnames.SnTable()) == 1) {
            return 4;
        }
        if (TgIs(ar, o, Pdfsnames.SnHyperlink()) == 1) {
            return 5;
        }
        return 6;
    }
    internal static int TgAdAdd(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells ad, int v) {
