            if (emon.Port.CellsLen(ad) < 24) {
                int ow = TgOwner(src, ar, dc, a, b, st, v);
                emon.Port.CellsPush(ad, v);
                emon.Port.CellsPush(ad, ow);
            }
            return 0;
        }
        if (Pdflex.PlKindOf(ar, v) == 6) {
            int e = Pdflex.PlFirst(ar, v);
            int eh = 0;
            int ow2 = 0;
            while (e != 0) {
                eh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
                if ((eh != 0) && (Pdflex.PlKindOf(ar, eh) == 7)) {
                    if (emon.Port.CellsLen(ad) < 24) {
                        ow2 = TgOwner(src, ar, dc, a, b, st, eh);
                        emon.Port.CellsPush(ad, eh);
                        emon.Port.CellsPush(ad, ow2);
