    }
    internal static int TgAttrs(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells ss, emon.Port.Cells ad, int eh) {
