            if (Pdflex.PlKindOf(ar, cv) == 4) {
                ent = Pdflex.PlNameEntry(ar, cv);
                vv = Pdflex.PlDictFind(ar, cm, ent);
                vv = Pdfdoc.PdResolve(src, ar, dc, a, b, st, vv);
                TgAdAdd(src, ar, dc, a, b, st, ad, vv);
