                    nh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
                    if ((nh != 0) && (Pdflex.PlKindOf(ar, nh) == 4)) {
                        ent = Pdflex.PlNameEntry(ar, nh);
                        vv = Pdflex.PlDictFind(ar, cm, ent);
                        vv = Pdfdoc.PdResolve(src, ar, dc, a, b, st, vv);
