            i += 2;
        }
        return 0;
    }
    internal static int TgReadAttrs(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells txt, emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells ad, int row, int eh, int role) {
