                        if (TgIs(ar, v, Pdfsnames.SnCircle()) == 1) {
                            emon.Port.CellsSet(se, at + SeListnum, 5);
                        }
                        if (TgIs(ar, v, Pdfsnames.SnSquare()) == 1) {
                            emon.Port.CellsSet(se, at + SeListnum, 6);
                        }
