            emon.Port.CellsSet(sk, sat + 1, row);
            emon.Port.CellsSet(sk, sat + 2, 0);
            emon.Port.CellsSet(se, pat + SeNobjr, emon.Port.CellsAt(se, pat + SeNobjr) + 1);
            return 0;
        }
        if (isel == 1) {
            if (((emon.Port.CellsLen(se) / SeStride) + 1) >= TgMaxelems) {
                emon.Port.CellsSet(sk, sat + 2, 4);
                emon.Port.CellsSet(ss, SsLimits, emon.Port.CellsAt(ss, SsLimits) | 1);
                return 0;
            }
            if ((depth + 1) >= TgMaxdepth) {
                emon.Port.CellsSet(sk, sat + 2, 3);
                emon.Port.CellsSet(ss, SsLimits, emon.Port.CellsAt(ss, SsLimits) | 2);
                emon.Port.CellsSet(se, pat + SeBits, emon.Port.CellsAt(se, pat + SeBits) | 32);
                return 0;
            }
            obj = TgObjOf(ar, raw);
            if (obj > 0) {
                if (Pdfx.PxSeenMark(seen, obj) == 1) {
                    emon.Port.CellsSet(sk, sat + 2, 2);
                    emon.Port.CellsSet(ss, SsLimits, emon.Port.CellsAt(ss, SsLimits) | 8);
                    return 0;
                }
            }
            child = TgElem(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, eh, obj, parent, depth + 1);
            if (child < 0) {
                return -1;
            }
            emon.Port.CellsSet(sk, sat + 0, 1);
            emon.Port.CellsSet(sk, sat + 1, child);
            emon.Port.CellsSet(sk, sat + 2, 0);
            emon.Port.CellsSet(se, pat + SeNelem, emon.Port.CellsAt(se, pat + SeNelem) + 1);
            return 0;
        }
        emon.Port.CellsSet(sk, sat + 2, 6);
        return 0;
    }
    internal static int TgKids(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells txt, emon.Port.Cells seen, emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells sk, emon.Port.Cells sc, emon.Port.Cells so, emon.Port.Cells ad, int row, int kraw, int depth) {
        // Read element `row`'s /K (raw value kraw): reserve one `sk` row per entry, then read each.
        int kh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, kraw);
        int at = row * SeStride;
        int first = emon.Port.CellsLen(sk) / SkStride;
        int n = 1;
        int i = 0;
        int e = 0;
        int r = 0;
        if (kh == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, kh) == 6) {
            n = Pdflex.PlCount(ar, kh);
        }
        if (n > 1000000) {
            n = 1000000;
        }
        while (i < (n * SkStride)) {
            emon.Port.CellsPush(sk, 0);
            i += 1;
        }
        emon.Port.CellsSet(se, at + SeKfirst, first);
        emon.Port.CellsSet(se, at + SeKcount, n);
        if (Pdflex.PlKindOf(ar, kh) == 6) {
            e = Pdflex.PlFirst(ar, kh);
            i = 0;
            while ((e != 0) && (i < n)) {
                r = TgKid(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, row, first + i, e, depth);
                if (r < 0) {
                    return -1;
                }
                i += 1;
                e = Pdflex.PlNext(ar, e);
            }
        } else {
            r = TgKid(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, row, first, kraw, depth);
            if (r < 0) {
                return -1;
            }
        }
        return 0;
    }
    internal static int TgElem(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells txt, emon.Port.Cells seen, emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells sk, emon.Port.Cells sc, emon.Port.Cells so, emon.Port.Cells ad, int eh, int obj, int parent, int depth) {
        // Read the structure element dictionary eh (object number obj, 0 direct) as a child of row
        // `parent`, then its kids. Answers its row, or -1 when the source missed.
        int row = TgSeNew(se, obj, parent, depth);
        int at = row * SeStride;
        int pat = parent * SeStride;
        int sh = 0;
        int rr = 0;
        int code = 0;
        int how = 0;
        int lvl = 0;
        int v = 0;
        int pgi = 0;
        int bits = 0;
        int sd = 0;
        int hl = 0;
        int prole = 0;
        int kraw = 0;
        int rc = 0;
        if (depth > emon.Port.CellsAt(ss, SsMaxdepth)) {
            emon.Port.CellsSet(ss, SsMaxdepth, depth);
        }
        emon.Port.CellsSet(ss, SsElems, emon.Port.CellsAt(ss, SsElems) + 1);
        sh = TgDget(src, ar, dc, a, b, st, eh, Pdfsnames.SnS());
        if ((sh != 0) && (Pdflex.PlKindOf(ar, sh) == 4)) {
            TgText(ar, sh, txt, se, at + SeRoles);
            rr = TgResolveRole(src, ar, dc, a, b, st, ss, sh);
            code = rr % 256;
            how = (rr / 256) % 256;
            lvl = rr / 65536;
        } else {
            how = 4;
        }
        emon.Port.CellsSet(se, at + SeRole, code);
        emon.Port.CellsSet(se, at + SeHow, how);
        emon.Port.CellsSet(se, at + SeLevel, lvl);
        if (how == 1) {
            emon.Port.CellsSet(ss, SsCustom, emon.Port.CellsAt(ss, SsCustom) + 1);
        }
        if ((how == 2) || (how == 3)) {
            emon.Port.CellsSet(ss, SsUnresolved, emon.Port.CellsAt(ss, SsUnresolved) + 1);
        }
        if (how == 5) {
            bits |= 16;
            emon.Port.CellsSet(ss, SsShadowed, emon.Port.CellsAt(ss, SsShadowed) + 1);
        }
        pgi = TgPageOf(src, ar, dc, a, b, st, idx, eh);
        if (pgi >= 0) {
            emon.Port.CellsSet(se, at + SePg, pgi);
            emon.Port.CellsSet(se, at + SePgown, 1);
        } else {
            emon.Port.CellsSet(se, at + SePg, emon.Port.CellsAt(se, pat + SePg));
        }
        v = TgDget(src, ar, dc, a, b, st, eh, Pdfsnames.SnAlt());
        TgText(ar, v, txt, se, at + SeAlt);
        v = TgDget(src, ar, dc, a, b, st, eh, Pdfsnames.SnActualText());
        TgText(ar, v, txt, se, at + SeAct);
        v = TgDget(src, ar, dc, a, b, st, eh, Pdfsnames.SnE());
        TgText(ar, v, txt, se, at + SeExp);
        v = TgDget(src, ar, dc, a, b, st, eh, Pdfsnames.SnLang());
        TgText(ar, v, txt, se, at + SeLang);
        v = TgDget(src, ar, dc, a, b, st, eh, Pdfsnames.SnId());
        TgText(ar, v, txt, se, at + SeId);
        v = TgDget(src, ar, dc, a, b, st, eh, Pdfsnames.SnT());
        TgText(ar, v, txt, se, at + SeTitle);
        if (emon.Port.CellsAt(se, at + SeLang) >= 0) {
            emon.Port.CellsSet(se, at + SeLangsrc, row);
        } else {
            emon.Port.CellsSet(se, at + SeLangsrc, emon.Port.CellsAt(se, pat + SeLangsrc));
        }
        prole = emon.Port.CellsAt(se, pat + SeRole);
        sd = emon.Port.CellsAt(se, pat + SeSdepth);
        if (prole == RoSect) {
            sd += 1;
        }
        emon.Port.CellsSet(se, at + SeSdepth, sd);
        if ((code == RoH) || (code == RoHn) || (code == RoTitle)) {
            emon.Port.CellsSet(se, at + SeInh, 1);
        } else {
            emon.Port.CellsSet(se, at + SeInh, emon.Port.CellsAt(se, pat + SeInh));
        }
        if (code == RoHn) {
            emon.Port.CellsSet(se, at + SeHlev, TgMin(lvl, 99));
        }
        if (code == RoH) {
            hl = TgMin(TgMax(sd, 1), 6);
            emon.Port.CellsSet(se, at + SeHlev, hl);
            bits |= 1;
        }
        if (TgGet(ar, eh, Pdfsnames.SnA()) != 0) {
            bits |= 2;
        }
        if (TgGet(ar, eh, Pdfsnames.SnC()) != 0) {
            bits |= 4;
        }
        if (obj == 0) {
            bits |= 8;
        }
        kraw = TgGet(ar, eh, Pdfsnames.SnK());
        if (kraw != 0) {
            bits |= 64;
        }
        emon.Port.CellsSet(se, at + SeBits, emon.Port.CellsAt(se, at + SeBits) | bits);
        rc = TgReadAttrs(src, ar, dc, a, b, st, txt, ss, se, ad, row, eh, code);
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        if (kraw != 0) {
            rc = TgKids(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, row, kraw, depth);
            if (rc < 0) {
                return -1;
            }
        }
        emon.Port.CellsSet(se, at + SeSize, (emon.Port.CellsLen(se) / SeStride) - row);
        return row;
    }
    internal static int TgNums(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells ss, int node, int depth, emon.Port.Cells @out) {
        // Every (integer key, raw value) of a number tree, appended to `out` two cells a pair: the
        // ParentTree. At most 12 deep and `TG_MAXPT` nodes; a loop costs that and no more.
        if (depth > 12) {
            return 0;
        }
        if (node == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, node) != 7) {
            return 0;
        }
        int left = emon.Port.CellsAt(ss, SsBudget);
        if (left <= 0) {
            return 0;
        }
        emon.Port.CellsSet(ss, SsBudget, left - 1);
        int nums = TgDget(src, ar, dc, a, b, st, node, Pdfsnames.SnNums());
        int kids = TgDget(src, ar, dc, a, b, st, node, Pdfsnames.SnKids());
        int k = 0;
        int v = 0;
        int kr = 0;
        if ((nums != 0) && (Pdflex.PlKindOf(ar, nums) == 6)) {
            k = Pdflex.PlFirst(ar, nums);
            while (k != 0) {
                v = Pdflex.PlNext(ar, k);
                if (v == 0) {
                    k = 0;
                } else {
                    kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                    if ((kr != 0) && (Pdflex.PlKindOf(ar, kr) == 2)) {
                        emon.Port.CellsPush(@out, Pdflex.PlIntValue(ar, kr));
                        emon.Port.CellsPush(@out, v);
                    }
                    k = Pdflex.PlNext(ar, v);
                }
            }
        }
        if ((kids != 0) && (Pdflex.PlKindOf(ar, kids) == 6)) {
            k = Pdflex.PlFirst(ar, kids);
            while (k != 0) {
                kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                TgNums(src, ar, dc, a, b, st, ss, kr, depth + 1, @out);
                k = Pdflex.PlNext(ar, k);
            }
        }
        return 0;
    }
    internal static int TgKeyOf(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int d, int id) {
        // The integer under key `id` of dictionary d (/StructParents, /StructParent), -1 when absent.
        int v = TgDget(src, ar, dc, a, b, st, d, id);
        if (v == 0) {
            return -1;
        }
        return Pdfx.PxIntOf(ar, v, -1);
    }
    internal static int TgParentTree(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells w, emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells sc, emon.Port.Cells so, emon.Port.Cells wk, int rooth) {
        // Verify the tree against its ParentTree: for every marked-content reference, the entry the
        // ParentTree holds for (the page's or the Form XObject's /StructParents, MCID) must be the
        // element that claims it; for every object reference, the object's /StructParent entry.
        emon.Port.CellsDrop(w, 0);
        int ptree = TgDget(src, ar, dc, a, b, st, rooth, Pdfsnames.SnParentTree());
        int nsc = emon.Port.CellsLen(sc) / ScStride;
        int nso = emon.Port.CellsLen(so) / SoStride;
        int i = 0;
        int key = 0;
        int pi = 0;
        int at = 0;
        int stm = 0;
        int mcid = 0;
        int dict = 0;
        int vh = 0;
        int ent = 0;
        int want = 0;
        int flag = 0;
        int npairs = 0;
        int got = 0;
        emon.Port.CellsSet(ss, SsBudget, TgMaxpt);
        TgNums(src, ar, dc, a, b, st, ss, ptree, 0, w);
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        npairs = emon.Port.CellsLen(w) / 2;
        emon.Port.CellsSet(ss, SsPtkeys, npairs);
        TgHtInit(wk, npairs);
        i = 0;
        while (i < npairs) {
            TgHtPut(wk, emon.Port.CellsAt(w, i * 2), 0, 0, i);
            i += 1;
        }
        i = 0;
        while (i < nsc) {
            at = i * ScStride;
            pi = emon.Port.CellsAt(sc, at + ScPage);
            stm = emon.Port.CellsAt(sc, at + ScStm);
            mcid = emon.Port.CellsAt(sc, at + ScMcid);
            flag = 0;
            key = -1;
            if ((mcid >= 0) && (pi >= 0) && (pi < Pdfdoc.PdPgCount(pg))) {
                if (stm == 0) {
                    dict = Pdfdoc.PdResolve(src, ar, dc, a, b, st, Pdfdoc.PdPgNode(pg, pi));
                } else {
                    dict = Pdfdoc.PdGet(src, ar, dc, a, b, st, stm);
                }
                if (dict != 0) {
                    key = TgKeyOf(src, ar, dc, a, b, st, dict, Pdfsnames.SnStructParents());
                }
            }
            if (key >= 0) {
                got = TgHtGet(wk, key, 0, 0);
                if (got >= 0) {
                    vh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, emon.Port.CellsAt(w, (got * 2) + 1));
                    if ((vh != 0) && (Pdflex.PlKindOf(ar, vh) == 6)) {
                        ent = Pdfx.PxNth(ar, vh, mcid);
                        want = emon.Port.CellsAt(se, (emon.Port.CellsAt(sc, at + ScElem) * SeStride) + SeObj);
                        if ((ent != 0) && (Pdflex.PlKindOf(ar, ent) == 9)) {
                            if ((want == 0) || (Pdflex.PlIntValue(ar, ent) == want)) {
                                flag = 16;
                            } else {
                                flag = 32;
                            }
                        } else {
                            flag = 64;
                        }
                    } else {
                        flag = 64;
                    }
                } else {
                    flag = 64;
                }
            } else {
                flag = 64;
            }
            if ((emon.Port.CellsAt(sc, at + ScFlags) & 128) == 128) {
                flag = 0;
            }
            if (flag == 16) {
                emon.Port.CellsSet(ss, SsPtok, emon.Port.CellsAt(ss, SsPtok) + 1);
            }
            if (flag == 32) {
                emon.Port.CellsSet(ss, SsPtbad, emon.Port.CellsAt(ss, SsPtbad) + 1);
            }
            if (flag == 64) {
                emon.Port.CellsSet(ss, SsPtnone, emon.Port.CellsAt(ss, SsPtnone) + 1);
            }
            emon.Port.CellsSet(sc, at + ScFlags, emon.Port.CellsAt(sc, at + ScFlags) | flag);
            i += 1;
        }
        i = 0;
        while (i < nso) {
            at = i * SoStride;
            want = emon.Port.CellsAt(se, (emon.Port.CellsAt(so, at) * SeStride) + SeObj);
            dict = Pdfdoc.PdGet(src, ar, dc, a, b, st, emon.Port.CellsAt(so, at + 2));
            key = -1;
            if (dict != 0) {
                key = TgKeyOf(src, ar, dc, a, b, st, dict, Pdfsnames.SnStructParent());
            }
            flag = 3;
            if (key >= 0) {
                got = TgHtGet(wk, key, 0, 0);
                if (got >= 0) {
                    ent = emon.Port.CellsAt(w, (got * 2) + 1);
                    if ((ent != 0) && (Pdflex.PlKindOf(ar, ent) == 9)) {
                        if ((want == 0) || (Pdflex.PlIntValue(ar, ent) == want)) {
                            flag = 1;
                        } else {
                            flag = 2;
                        }
                    }
                }
            }
            emon.Port.CellsSet(so, at + 4, flag);
            i += 1;
        }
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        return 0;
    }
    public static int TgRead(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells idx, emon.Port.Cells txt, emon.Port.Cells w, emon.Port.Cells seen, emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells sk, emon.Port.Cells sc, emon.Port.Cells so, emon.Port.Cells wk, emon.Port.Cells md) {
        // The structure tree of an opened document (`pd-open` 0, `pd-pages`, `px-index-build`): the
        // catalog's /MarkInfo and /Lang, the StructTreeRoot, its RoleMap and ClassMap, every element, and
        // the ParentTree check. `ss se sk sc so` are cleared; `txt` is APPENDED to; `w` and `wk` are scratch;
        // `md` is `emon.pdfmeta`'s header (empty when it has not run: the PDF/UA part is then -1).
        // Answers the number of elements (0 when the document is not tagged), or -1 when the source missed
        // (re-run on a fresh view; nothing here is kept).
        emon.Port.CellsDrop(ss, 0);
        emon.Port.CellsDrop(se, 0);
        emon.Port.CellsDrop(sk, 0);
        emon.Port.CellsDrop(sc, 0);
        emon.Port.CellsDrop(so, 0);
        int i = 0;
        int root = Pdfdoc.PdRoot(dc);
        int mi = 0;
        int v = 0;
        int sroot = 0;
        int rm = 0;
        int cm = 0;
        int rc = 0;
        int kraw = 0;
        int robj = 0;
        while (i < SsSize) {
            emon.Port.CellsPush(ss, 0);
            i += 1;
        }
        emon.Port.CellsSet(ss, SsMarked, -1);
        emon.Port.CellsSet(ss, SsSuspects, -1);
        emon.Port.CellsSet(ss, SsUserprops, -1);
        emon.Port.CellsSet(ss, SsUapart, -1);
        emon.Port.CellsSet(ss, SsUarev, -1);
        emon.Port.CellsSet(ss, SsLang, -1);
        emon.Port.CellsSet(ss, SsCov, -1);
        emon.Port.CellsSet(ss, SsDiv, -1);
        emon.Port.CellsSet(ss, SsOrd, -1);
        emon.Port.CellsSet(ss, SsHdr, -1);
        emon.Port.CellsSet(ss, SsLv, -1);
        emon.Port.CellsSet(ss, SsArt, -1);
        emon.Port.CellsSet(ss, SsNestr, -1);
        emon.Port.CellsSet(ss, SsRootobj, 0);
        emon.Port.CellsSet(ss, SsPages, Pdfdoc.PdPgCount(pg));
        if (root == 0) {
            return 0;
        }
        mi = TgDget(src, ar, dc, a, b, st, root, Pdfsnames.SnMarkInfo());
        if ((mi != 0) && (Pdflex.PlKindOf(ar, mi) == 7)) {
            v = TgDget(src, ar, dc, a, b, st, mi, Pdfsnames.SnMarked());
            if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 1)) {
                emon.Port.CellsSet(ss, SsMarked, Pdflex.PlIntValue(ar, v));
            }
            v = TgDget(src, ar, dc, a, b, st, mi, Pdfsnames.SnSuspects());
            if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 1)) {
                emon.Port.CellsSet(ss, SsSuspects, Pdflex.PlIntValue(ar, v));
            }
            v = TgDget(src, ar, dc, a, b, st, mi, Pdfsnames.SnUserProperties());
            if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 1)) {
                emon.Port.CellsSet(ss, SsUserprops, Pdflex.PlIntValue(ar, v));
            }
        }
        if (emon.Port.CellsLen(md) > 59) {
            emon.Port.CellsSet(ss, SsUapart, emon.Port.CellsAt(md, 42));
            emon.Port.CellsSet(ss, SsUarev, emon.Port.CellsAt(md, 59));
            emon.Port.CellsSet(ss, SsLang, emon.Port.CellsAt(md, 0));
            emon.Port.CellsSet(ss, SsLang + 1, emon.Port.CellsAt(md, 1));
        }
        sroot = TgDget(src, ar, dc, a, b, st, root, Pdfsnames.SnStructTreeRoot());
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        if (sroot == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, sroot) != 7) {
            return 0;
        }
        emon.Port.CellsSet(ss, SsPresent, 1);
        emon.Port.CellsSet(ss, SsRoot, sroot);
        Pdfx.PxSeenBegin(seen, Pdfdoc.PdObjectCount(dc));
        rm = TgDget(src, ar, dc, a, b, st, sroot, Pdfsnames.SnRoleMap());
        if ((rm != 0) && (Pdflex.PlKindOf(ar, rm) == 7)) {
            emon.Port.CellsSet(ss, SsRolemap, rm);
            emon.Port.CellsSet(ss, SsRolemapn, Pdflex.PlCount(ar, rm) / 2);
        }
        cm = TgDget(src, ar, dc, a, b, st, sroot, Pdfsnames.SnClassMap());
        if ((cm != 0) && (Pdflex.PlKindOf(ar, cm) == 7)) {
            emon.Port.CellsSet(ss, SsClassmap, cm);
            emon.Port.CellsSet(ss, SsClassmapn, Pdflex.PlCount(ar, cm) / 2);
        }
        robj = TgGet(ar, root, Pdfsnames.SnStructTreeRoot());
        robj = TgObjOf(ar, robj);
        TgSeNew(se, robj, -1, 0);
        emon.Port.CellsSet(ss, SsRootobj, emon.Port.CellsAt(se, SeObj));
        emon.Port.CellsSet(se, SeHow, 6);
        emon.Port.CellsSet(se, SeBits, 0);
        emon.Port.CellsSet(ss, SsElems, 1);
        emon.Port.CellsSet(ss, SsCbudget, 0);
        kraw = TgGet(ar, sroot, Pdfsnames.SnK());
        if (kraw != 0) {
            emon.Port.CellsSet(se, SeBits, 64);
            rc = TgKids(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, w, 0, kraw, 0);
            if (rc < 0) {
                return -1;
            }
        }
        emon.Port.CellsSet(se, SeSize, emon.Port.CellsLen(se) / SeStride);
        emon.Port.CellsSet(ss, SsContent, emon.Port.CellsLen(sc) / ScStride);
        emon.Port.CellsSet(ss, SsObjrs, emon.Port.CellsLen(so) / SoStride);
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        rc = TgParentTree(src, ar, dc, a, b, st, pg, w, ss, se, sc, so, wk, sroot);
        if (rc < 0) {
            return -1;
        }
        return emon.Port.CellsLen(se) / SeStride;
    }
    internal static int TgJMarks(emon.Port.Cells ss, emon.Port.Cells sc, emon.Port.Cells mk, emon.Port.Cells ha, emon.Port.Cells hb) {
        // Index the text layer's marked content by (page, Form XObject, MCID) and join every marked-
        // content reference to its `marks` row. A mark claimed twice keeps its first claimer (the other
        // reference is flagged `duplicate`); the rest is `no-mark`.
        int nmk = Evidence.MkCount(mk);
        int nsc = emon.Port.CellsLen(sc) / ScStride;
        int m = 0;
        int mc = 0;
        int i = 0;
        int at = 0;
        int pi = 0;
        int got = 0;
        int fl = 0;
        int dup = 0;
        TgHtInit(ha, nmk);
        emon.Port.CellsDrop(hb, 0);
        while (m < nmk) {
            emon.Port.CellsPush(hb, -1);
            mc = Evidence.MkGet(mk, m, Evidence.MkfMcid());
            if (mc >= 0) {
                dup = TgHtPut(ha, Evidence.MkGet(mk, m, Evidence.MkfPage()), Evidence.MkGet(mk, m, Evidence.MkfStm()), mc, m);
            }
            m += 1;
        }
        emon.Port.CellsSet(ss, SsMarks, nmk);
        while (i < nsc) {
            at = i * ScStride;
            pi = emon.Port.CellsAt(sc, at + ScPage);
            fl = emon.Port.CellsAt(sc, at + ScFlags);
            got = -1;
            if ((pi >= 0) && (emon.Port.CellsAt(sc, at + ScMcid) >= 0)) {
                got = TgHtGet(ha, pi + 1, emon.Port.CellsAt(sc, at + ScStm), emon.Port.CellsAt(sc, at + ScMcid));
            }
            if (got >= 0) {
                emon.Port.CellsSet(sc, at + ScMark, got);
                emon.Port.CellsSet(sc, at + ScGfirst, Evidence.MkGet(mk, got, Evidence.MkfGfirst()));
                emon.Port.CellsSet(sc, at + ScGcount, Evidence.MkGet(mk, got, Evidence.MkfGcount()));
                if (emon.Port.CellsAt(hb, got) >= 0) {
                    fl |= 8;
                    emon.Port.CellsSet(ss, SsDups, emon.Port.CellsAt(ss, SsDups) + 1);
                } else {
                    emon.Port.CellsSet(hb, got, i);
                }
                emon.Port.CellsSet(ss, SsJoined, emon.Port.CellsAt(ss, SsJoined) + 1);
            } else {
                fl |= 4;
                emon.Port.CellsSet(ss, SsUnjoined, emon.Port.CellsAt(ss, SsUnjoined) + 1);
            }
            emon.Port.CellsSet(sc, at + ScFlags, fl);
            i += 1;
        }
        return dup;
    }
    internal static int TgJGlyphs(emon.Port.Cells ss, emon.Port.Cells sc, emon.Port.Cells gl, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells hb, emon.Port.Cells hh) {
        // Give every glyph its owner: the structure element of its innermost marked content that carries an
        // MCID (through the reference that claimed it), or `artifact` (innermost /Artifact), or neither. The
        // owning reference collects the glyph's size, boldness and box; the type-size histogram `hh` (0.5 pt
        // buckets) collects every tagged glyph, for the body size.
        int ng = Evidence.GlCount(gl);
        int g = 0;
        int m = 0;
        int decided = 0;
        int own = -1;
        int at = 0;
        int sz = 0;
        int bold = 0;
        int font = 0;
        int bk = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int n = 0;
        emon.Port.CellsDrop(hh, 0);
        while (n < 4200) {
            emon.Port.CellsPush(hh, 0);
            n += 1;
        }
        emon.Port.CellsSet(ss, SsGlyphs, ng);
        while (g < ng) {
            m = Evidence.GlGet(gl, g, Evidence.GfMark());
            decided = 0;
            own = -1;
            while ((m >= 0) && (decided == 0)) {
                if (Evidence.MkGet(mk, m, Evidence.MkfKind()) == 1) {
                    decided = 2;
                } else if (Evidence.MkGet(mk, m, Evidence.MkfMcid()) >= 0) {
                    decided = 1;
                    own = emon.Port.CellsAt(hb, m);
                }
                if (decided == 0) {
                    m = Evidence.MkGet(mk, m, Evidence.MkfParent());
                }
            }
            if (decided == 2) {
                emon.Port.CellsSet(ss, SsArtg, emon.Port.CellsAt(ss, SsArtg) + 1);
            }
            if (decided == 0) {
                emon.Port.CellsSet(ss, SsUntagged, emon.Port.CellsAt(ss, SsUntagged) + 1);
            }
            if ((decided == 1) && (own < 0)) {
                emon.Port.CellsSet(ss, SsUnclaimed, emon.Port.CellsAt(ss, SsUnclaimed) + 1);
            }
            if ((decided == 1) && (own >= 0)) {
                emon.Port.CellsSet(ss, SsCovered, emon.Port.CellsAt(ss, SsCovered) + 1);
                at = own * ScStride;
                sz = Evidence.GlGet(gl, g, Evidence.GfSize());
                bk = TgMin(sz / 50, 4095);
                if (bk < 0) {
                    bk = 0;
                }
                emon.Port.CellsSet(hh, bk, emon.Port.CellsAt(hh, bk) + 1);
                sz = (TgMin(TgMax(sz, 0), 6000) + 5) / 10;
                font = Evidence.GlGet(gl, g, Evidence.GfFont());
                bold = 0;
                if (font >= 0) {
                    if ((Evidence.FoGet(fnt, font, Evidence.FnfStyle()) & 1) == 1) {
                        bold = 1;
                    }
                }
                x0 = Evidence.GlGet(gl, g, Evidence.ChX0());
                y0 = Evidence.GlGet(gl, g, Evidence.ChY0());
                x1 = Evidence.GlGet(gl, g, Evidence.ChX1());
                y1 = Evidence.GlGet(gl, g, Evidence.ChY1());
                if (emon.Port.CellsAt(sc, at + ScOwng) == 0) {
                    emon.Port.CellsSet(sc, at + ScBx0, x0);
                    emon.Port.CellsSet(sc, at + (ScBx0 + 1), y0);
                    emon.Port.CellsSet(sc, at + (ScBx0 + 2), x1);
                    emon.Port.CellsSet(sc, at + (ScBx0 + 3), y1);
                    emon.Port.CellsSet(sc, at + ScFirstg, g);
                } else {
                    emon.Port.CellsSet(sc, at + ScBx0, TgMin(emon.Port.CellsAt(sc, at + ScBx0), x0));
                    emon.Port.CellsSet(sc, at + (ScBx0 + 1), TgMin(emon.Port.CellsAt(sc, at + (ScBx0 + 1)), y0));
                    emon.Port.CellsSet(sc, at + (ScBx0 + 2), TgMax(emon.Port.CellsAt(sc, at + (ScBx0 + 2)), x1));
                    emon.Port.CellsSet(sc, at + (ScBx0 + 3), TgMax(emon.Port.CellsAt(sc, at + (ScBx0 + 3)), y1));
                }
                emon.Port.CellsSet(sc, at + ScLastg, g);
                emon.Port.CellsSet(sc, at + ScOwng, emon.Port.CellsAt(sc, at + ScOwng) + 1);
                emon.Port.CellsSet(sc, at + ScOwnsz, emon.Port.CellsAt(sc, at + ScOwnsz) + sz);
                emon.Port.CellsSet(sc, at + ScOwnbd, emon.Port.CellsAt(sc, at + ScOwnbd) + bold);
            }
            g += 1;
        }
        return 0;
    }
    internal static int TgJSub(emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells sc, emon.Port.Cells so) {
        // Roll every marked-content reference's glyphs up its element's ancestors: the element's own
        // numbers, then the subtree's, the first reference (in tree order) that holds text and the box of
        // the subtree's text on that reference's page.
        int nsc = emon.Port.CellsLen(sc) / ScStride;
        int nso = emon.Port.CellsLen(so) / SoStride;
        int i = 0;
        int at = 0;
        int e = 0;
        int ea = 0;
        int g = 0;
        int pgx = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        while (i < nsc) {
            at = i * ScStride;
            e = emon.Port.CellsAt(sc, at + ScElem);
            g = emon.Port.CellsAt(sc, at + ScOwng);
            pgx = emon.Port.CellsAt(sc, at + ScPage);
            x0 = emon.Port.CellsAt(sc, at + ScBx0);
            y0 = emon.Port.CellsAt(sc, at + (ScBx0 + 1));
            x1 = emon.Port.CellsAt(sc, at + (ScBx0 + 2));
            y1 = emon.Port.CellsAt(sc, at + (ScBx0 + 3));
            ea = e * SeStride;
            emon.Port.CellsSet(se, ea + SeOwng, emon.Port.CellsAt(se, ea + SeOwng) + g);
            emon.Port.CellsSet(se, ea + SeOwnsz, emon.Port.CellsAt(se, ea + SeOwnsz) + emon.Port.CellsAt(sc, at + ScOwnsz));
            emon.Port.CellsSet(se, ea + SeOwnbd, emon.Port.CellsAt(se, ea + SeOwnbd) + emon.Port.CellsAt(sc, at + ScOwnbd));
            while (e >= 0) {
                ea = e * SeStride;
                emon.Port.CellsSet(se, ea + SeSubc, emon.Port.CellsAt(se, ea + SeSubc) + 1);
                if (g > 0) {
                    emon.Port.CellsSet(se, ea + SeSubg, emon.Port.CellsAt(se, ea + SeSubg) + g);
                    emon.Port.CellsSet(se, ea + SeSubsz, emon.Port.CellsAt(se, ea + SeSubsz) + emon.Port.CellsAt(sc, at + ScOwnsz));
                    emon.Port.CellsSet(se, ea + SeSubbd, emon.Port.CellsAt(se, ea + SeSubbd) + emon.Port.CellsAt(sc, at + ScOwnbd));
                    if (emon.Port.CellsAt(se, ea + SeFsc) < 0) {
                        emon.Port.CellsSet(se, ea + SeFsc, i);
                        emon.Port.CellsSet(se, ea + SeFpg, pgx);
                        emon.Port.CellsSet(se, ea + SeBx0, x0);
                        emon.Port.CellsSet(se, ea + (SeBx0 + 1), y0);
                        emon.Port.CellsSet(se, ea + (SeBx0 + 2), x1);
                        emon.Port.CellsSet(se, ea + (SeBx0 + 3), y1);
                    } else if (emon.Port.CellsAt(se, ea + SeFpg) == pgx) {
                        emon.Port.CellsSet(se, ea + SeBx0, TgMin(emon.Port.CellsAt(se, ea + SeBx0), x0));
                        emon.Port.CellsSet(se, ea + (SeBx0 + 1), TgMin(emon.Port.CellsAt(se, ea + (SeBx0 + 1)), y0));
                        emon.Port.CellsSet(se, ea + (SeBx0 + 2), TgMax(emon.Port.CellsAt(se, ea + (SeBx0 + 2)), x1));
                        emon.Port.CellsSet(se, ea + (SeBx0 + 3), TgMax(emon.Port.CellsAt(se, ea + (SeBx0 + 3)), y1));
                    }
                }
                e = emon.Port.CellsAt(se, ea + SeParent);
            }
            i += 1;
        }
        i = 0;
        while (i < nso) {
            e = emon.Port.CellsAt(so, i * SoStride);
            while (e >= 0) {
                ea = e * SeStride;
                emon.Port.CellsSet(se, ea + SeSubc, emon.Port.CellsAt(se, ea + SeSubc) + 1);
                e = emon.Port.CellsAt(se, ea + SeParent);
            }
            i += 1;
        }
        return 0;
    }
    internal static int TgJOrder(emon.Port.Cells ss, emon.Port.Cells sc, emon.Port.Cells gl) {
        // Reading order against geometry: for each pair of consecutive marked-content references that hold
        // upright text on the same page, the tree is right when the second starts no more than half a line
        // above where the first ended (down the page, or along the line), or entirely to the right of it (the
        // next column). The glyph boxes are in page space, y down.
        int nsc = emon.Port.CellsLen(sc) / ScStride;
        int i = 0;
        int prev = -1;
        int ga = 0;
        int gb = 0;
        int ah = 0;
        int bh = 0;
        int h = 0;
        int up = 0;
        int agree = 0;
        while (i < nsc) {
            if (emon.Port.CellsAt(sc, (i * ScStride) + ScOwng) > 0) {
                if (prev >= 0) {
                    if (emon.Port.CellsAt(sc, (prev * ScStride) + ScPage) == emon.Port.CellsAt(sc, (i * ScStride) + ScPage)) {
                        ga = emon.Port.CellsAt(sc, (prev * ScStride) + ScLastg);
                        gb = emon.Port.CellsAt(sc, (i * ScStride) + ScFirstg);
                        if ((Evidence.GlGet(gl, ga, Evidence.GfRot()) == 0) && (Evidence.GlGet(gl, gb, Evidence.GfRot()) == 0)) {
                            ah = Evidence.GlGet(gl, ga, Evidence.ChY1()) - Evidence.GlGet(gl, ga, Evidence.ChY0());
                            bh = Evidence.GlGet(gl, gb, Evidence.ChY1()) - Evidence.GlGet(gl, gb, Evidence.ChY0());
                            h = TgMin(ah, bh);
                            if (h <= 0) {
                                h = TgMax(ah, bh);
                            }
                            up = (Evidence.GlGet(gl, ga, Evidence.ChY0()) + Evidence.GlGet(gl, ga, Evidence.ChY1())) - (Evidence.GlGet(gl, gb, Evidence.ChY0()) + Evidence.GlGet(gl, gb, Evidence.ChY1()));
                            agree = 0;
                            if (up <= h) {
                                agree = 1;
                            }
                            if (Evidence.GlGet(gl, gb, Evidence.ChX0()) >= Evidence.GlGet(gl, ga, Evidence.ChX1())) {
                                agree = 1;
                            }
                            emon.Port.CellsSet(ss, SsTrans, emon.Port.CellsAt(ss, SsTrans) + 1);
                            emon.Port.CellsSet(ss, SsTransok, emon.Port.CellsAt(ss, SsTransok) + agree);
                        }
                    }
                }
                prev = i;
            }
            i += 1;
        }
        return 0;
    }
    internal static int TgClassBit(int role) {
        // The class of informative structure a role belongs to, as a bit: 1 heading, 2 list, 4 table,
        // 8 figure, 16 section, 32 note-like (caption, quote, note, reference, code), 64 link, 128
        // table of contents. A paragraph, a span and the grouping types say nothing beyond blocks.
        if ((role == RoH) || (role == RoHn) || (role == RoTitle)) {
            return 1;
        }
        if ((role >= RoL) && (role <= RoLbody)) {
            return 2;
        }
        if ((role >= RoTable) && (role <= RoTfoot)) {
            return 4;
        }
        if ((role == RoFigure) || (role == RoFormula) || (role == RoForm)) {
            return 8;
        }
        if ((role == RoPart) || (role == RoArt) || (role == RoSect) || (role == RoAside)) {
            return 16;
        }
        if ((role == RoBlockquote) || (role == RoCaption) || (role == RoQuote) || (role == RoNote)) {
            return 32;
        }
        if ((role == RoFenote) || (role == RoRef) || (role == RoBib) || (role == RoCode)) {
            return 32;
        }
        if ((role == RoLink) || (role == RoAnnot)) {
            return 64;
        }
        if ((role >= RoToc) && (role <= RoIndex)) {
            return 128;
        }
        return 0;
    }
    internal static int TgNestOk(int role, int prole) {
        // Whether a role sits where the standard puts it: 1 yes, 0 no, -1 the standard says nothing.
        if (role == RoTr) {
            if ((prole == RoTable) || (prole == RoThead) || (prole == RoTbody) || (prole == RoTfoot)) {
                return 1;
            }
            return 0;
        }
        if ((role == RoTh) || (role == RoTd)) {
            if (prole == RoTr) {
                return 1;
            }
            return 0;
        }
        if ((role == RoThead) || (role == RoTbody) || (role == RoTfoot)) {
            if (prole == RoTable) {
                return 1;
            }
            return 0;
        }
        if (role == RoLi) {
            if (prole == RoL) {
                return 1;
            }
            return 0;
        }
        if ((role == RoLbl) || (role == RoLbody)) {
            if (prole == RoLi) {
                return 1;
            }
            return 0;
        }
        if (role == RoToci) {
            if ((prole == RoToc) || (prole == RoToci)) {
                return 1;
            }
            return 0;
        }
        return -1;
    }
    internal static int TgJClasses(emon.Port.Cells ss, emon.Port.Cells se) {
        // Which classes of structure the tree uses (over elements that hold content), and how many of the
        // roles the standard places are where it places them.
        int nse = emon.Port.CellsLen(se) / SeStride;
        int r = 1;
        int at = 0;
        int par = 0;
        int role = 0;
        int mask = 0;
        int v = 0;
        int bits = 0;
        int n = 0;
        while (r < nse) {
            at = r * SeStride;
            role = emon.Port.CellsAt(se, at + SeRole);
            par = emon.Port.CellsAt(se, at + SeParent);
            if (emon.Port.CellsAt(se, at + SeSubc) > 0) {
                mask |= TgClassBit(role);
            }
            v = TgNestOk(role, emon.Port.CellsAt(se, (par * SeStride) + SeRole));
            if (v >= 0) {
                emon.Port.CellsSet(ss, SsNest, emon.Port.CellsAt(ss, SsNest) + 1);
                emon.Port.CellsSet(ss, SsNestok, emon.Port.CellsAt(ss, SsNestok) + v);
            }
            if (role == RoTable) {
                emon.Port.CellsSet(ss, SsTables, emon.Port.CellsAt(ss, SsTables) + 1);
            }
            if (role == RoL) {
                emon.Port.CellsSet(ss, SsLists, emon.Port.CellsAt(ss, SsLists) + 1);
            }
            r += 1;
        }
        emon.Port.CellsSet(ss, SsClasses, mask);
        bits = mask;
        while (bits > 0) {
            n += bits % 2;
            bits = bits / 2;
        }
        emon.Port.CellsSet(ss, SsNclasses, n);
        return 0;
    }
    internal static int TgJTables(emon.Port.Cells sk, emon.Port.Cells se) {
        // Each table's shape from its rows: how many, how many columns (the sum of ColSpan over a row's
        // cells), and whether every row has as many (`regular`). Rows are found under the Table or its
        // THead, TBody and TFoot.
        int nse = emon.Port.CellsLen(se) / SeStride;
        int r = 1;
        int at = 0;
        int p = 0;
        int pr = 0;
        int k = 0;
        int kn = 0;
        int c = 0;
        int cols = 0;
        int cs = 0;
        int tat = 0;
        while (r < nse) {
            at = r * SeStride;
            if (emon.Port.CellsAt(se, at + SeRole) == RoTr) {
                p = emon.Port.CellsAt(se, at + SeParent);
                pr = emon.Port.CellsAt(se, (p * SeStride) + SeRole);
                if ((pr == RoThead) || (pr == RoTbody) || (pr == RoTfoot)) {
                    p = emon.Port.CellsAt(se, (p * SeStride) + SeParent);
                    pr = emon.Port.CellsAt(se, (p * SeStride) + SeRole);
                }
                if (pr == RoTable) {
                    cols = 0;
                    k = emon.Port.CellsAt(se, at + SeKfirst);
                    kn = emon.Port.CellsAt(se, at + SeKcount);
                    c = 0;
                    while ((k >= 0) && (c < kn)) {
                        if (emon.Port.CellsAt(sk, (k + c) * SkStride) == 1) {
                            cs = emon.Port.CellsAt(sk, ((k + c) * SkStride) + 1) * SeStride;
                            if ((emon.Port.CellsAt(se, cs + SeRole) == RoTh) || (emon.Port.CellsAt(se, cs + SeRole) == RoTd)) {
                                cols += TgMax(emon.Port.CellsAt(se, cs + SeColspan), 1);
                            }
                        }
                        c += 1;
                    }
                    tat = p * SeStride;
                    emon.Port.CellsSet(se, tat + SeTrows, emon.Port.CellsAt(se, tat + SeTrows) + 1);
                    if (emon.Port.CellsAt(se, tat + SeTrows) == 1) {
                        emon.Port.CellsSet(se, tat + SeTcols, cols);
                        emon.Port.CellsSet(se, tat + SeTreg, 1);
                    } else if (cols != emon.Port.CellsAt(se, tat + SeTcols)) {
                        emon.Port.CellsSet(se, tat + SeTreg, 0);
                        emon.Port.CellsSet(se, tat + SeTcols, TgMax(cols, emon.Port.CellsAt(se, tat + SeTcols)));
                    }
                }
            }
            r += 1;
        }
        return 0;
    }
    internal static int TgLabelKind(emon.Port.Cells gl, int g0, int g1) {
        // What a list label's first glyphs look like, as `lk` bits: a bullet, decimal digits, a letter (a
        // Roman numeral's letters count for both), several Roman letters; 0 when it is none. Leading
        // parentheses and spaces, a trailing period, the first space or `)` `:` `]` are not part of it.
        int g = g0;
        int cp = 0;
        int n = 0;
        int sym = 0;
        int dig = 0;
        int low = 0;
        int upr = 0;
        int rl = 0;
        int ru = 0;
        int stop = 0;
        int mask = 0;
        while ((g <= g1) && (g < (g0 + 12)) && (stop == 0)) {
            cp = Evidence.GlGet(gl, g, Evidence.ChCp());
            if ((cp == 32) || (cp == 160) || (cp == 41) || (cp == 58) || (cp == 93) || (cp == 40) || (cp == 91)) {
                if (n > 0) {
                    stop = 1;
                }
            } else if (cp != 46) {
                n += 1;
                if ((cp >= 48) && (cp <= 57)) {
                    dig += 1;
                }
                if ((cp >= 97) && (cp <= 122)) {
                    low += 1;
                    if ((cp == 105) || (cp == 118) || (cp == 120) || (cp == 108) || (cp == 99) || (cp == 100) || (cp == 109)) {
                        rl += 1;
                    }
                }
                if ((cp >= 65) && (cp <= 90)) {
                    upr += 1;
                    if ((cp == 73) || (cp == 86) || (cp == 88) || (cp == 76) || (cp == 67) || (cp == 68) || (cp == 77)) {
                        ru += 1;
                    }
                }
                if ((cp >= 0) && (cp < 48)) {
                    sym += 1;
                }
                if ((cp > 57) && (cp < 65)) {
                    sym += 1;
                }
                if ((cp > 90) && (cp < 97)) {
                    sym += 1;
                }
                if ((cp > 122) && (cp < 128)) {
                    sym += 1;
                }
                if ((cp >= 8192) && (cp <= 11263)) {
                    sym += 1;
                }
                if ((cp >= 57344) && (cp <= 63743)) {
                    sym += 1;
                }
            }
            g += 1;
        }
        if (n == 0) {
            return 0;
        }
        if (sym == n) {
            return 1;
        }
        if (dig == n) {
            return 2;
        }
        if (low == n) {
            mask = 4;
            if (rl == n) {
                mask = 20;
            }
            return mask;
        }
        if (upr == n) {
            mask = 8;
            if (ru == n) {
                mask = 40;
            }
            return mask;
        }
        return 0;
    }
    internal static int TgListWant(int ln) {
        // The label kinds (`lk` bits) a ListNumbering value allows; 0 when it says nothing to check.
        if ((ln == 2) || (ln == 4) || (ln == 5) || (ln == 6)) {
            return 1;
        }
        if (ln == 3) {
            return 62;
        }
        if (ln == 7) {
            return 2;
        }
        if (ln == 8) {
            return 32;
        }
        if (ln == 9) {
            return 16;
        }
        if (ln == 10) {
            return 8;
        }
        if (ln == 11) {
            return 4;
        }
        return 0;
    }
    internal static int TgJLists(emon.Port.Cells sk, emon.Port.Cells se, emon.Port.Cells sc, emon.Port.Cells gl) {
        // Each list: its items, the items with a label, and whether the first glyphs of each label look like
        // what the list's ListNumbering says (a bullet for Disc, digits for Decimal, ...).
        int nse = emon.Port.CellsLen(se) / SeStride;
        int r = 1;
        int at = 0;
        int k = 0;
        int kn = 0;
        int c = 0;
        int li = 0;
        int lat = 0;
        int j = 0;
        int jn = 0;
        int d = 0;
        int bl = 0;
        int bat = 0;
        int haslbl = 0;
        int want = 0;
        int kind = 0;
        int fsc = 0;
        int sat = 0;
        while (r < nse) {
            at = r * SeStride;
            if (emon.Port.CellsAt(se, at + SeRole) == RoL) {
                want = TgListWant(emon.Port.CellsAt(se, at + SeListnum));
                k = emon.Port.CellsAt(se, at + SeKfirst);
                kn = emon.Port.CellsAt(se, at + SeKcount);
                c = 0;
                while ((k >= 0) && (c < kn)) {
                    if (emon.Port.CellsAt(sk, (k + c) * SkStride) == 1) {
                        li = emon.Port.CellsAt(sk, ((k + c) * SkStride) + 1);
                        lat = li * SeStride;
                        if (emon.Port.CellsAt(se, lat + SeRole) == RoLi) {
                            emon.Port.CellsSet(se, at + SeLitems, emon.Port.CellsAt(se, at + SeLitems) + 1);
                            haslbl = 0;
                            j = emon.Port.CellsAt(se, lat + SeKfirst);
                            jn = emon.Port.CellsAt(se, lat + SeKcount);
                            d = 0;
                            while ((j >= 0) && (d < jn) && (haslbl == 0)) {
                                if (emon.Port.CellsAt(sk, (j + d) * SkStride) == 1) {
                                    bl = emon.Port.CellsAt(sk, ((j + d) * SkStride) + 1);
                                    bat = bl * SeStride;
                                    if (emon.Port.CellsAt(se, bat + SeRole) == RoLbl) {
                                        haslbl = 1;
                                        emon.Port.CellsSet(se, at + SeLlbl, emon.Port.CellsAt(se, at + SeLlbl) + 1);
                                        fsc = emon.Port.CellsAt(se, bat + SeFsc);
                                        kind = 0;
                                        if (fsc >= 0) {
                                            sat = fsc * ScStride;
                                            kind = TgLabelKind(gl, emon.Port.CellsAt(sc, sat + ScFirstg), emon.Port.CellsAt(sc, sat + ScLastg));
                                        }
                                        if (emon.Port.CellsAt(se, at + SeLkind) == 0) {
                                            emon.Port.CellsSet(se, at + SeLkind, kind);
                                        }
                                        if ((want > 0) && (kind > 0)) {
                                            if ((want & kind) > 0) {
                                                emon.Port.CellsSet(se, at + SeLok, emon.Port.CellsAt(se, at + SeLok) + 1);
                                            } else {
                                                emon.Port.CellsSet(se, at + SeLbad, emon.Port.CellsAt(se, at + SeLbad) + 1);
                                            }
                                        }
                                    }
                                }
                                d += 1;
                            }
                        }
                    }
                    c += 1;
                }
            }
            r += 1;
        }
        return 0;
    }
    internal static int TgMean(int sum, int n) {
        // sum * 10 / n in centipoints (sums are tenths of a point), without overflow.
        if (n <= 0) {
            return 0;
        }
        return ((sum / n) * 10) + (((sum % n) * 10) / n);
    }
    internal static int TgJHeadings(emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells hh) {
        // Heading roles against the page. The BODY SIZE is the most common size of tagged text. A heading
        // (an element inside H, Hn or Title, with text of its own) is verified when its type is clearly larger
        // than the body or is bold and not smaller; a BIG element is short text at least 1.25 times the body
        // that is not a table cell, a label, a figure or a formula, and is a miss when it is no heading. Heading
        // LEVELS are checked two ways: in document order a level may not jump by more than one, and a
        // lower level number may not be set smaller than a higher one.
        int nse = emon.Port.CellsLen(se) / SeStride;
        int b = 0;
        int best = 0;
        int bestn = 0;
        int body = 0;
        int r = 1;
        int at = 0;
        int g = 0;
        int mean = 0;
        int bold = 0;
        int role = 0;
        int inh = 0;
        int lvl = 0;
        int prevl = 0;
        int skip = 0;
        int l = 0;
        int pl = 0;
        int pmean = 0;
        int cmean = 0;
        while (b < 4096) {
            if (emon.Port.CellsAt(hh, b) > bestn) {
                bestn = emon.Port.CellsAt(hh, b);
                best = b;
            }
            b += 1;
        }
        if (bestn > 0) {
            body = (best * 50) + 25;
        }
        emon.Port.CellsSet(ss, SsBody, body);
        if (body == 0) {
            return 0;
        }
        while (r < nse) {
            at = r * SeStride;
            g = emon.Port.CellsAt(se, at + SeOwng);
            role = emon.Port.CellsAt(se, at + SeRole);
            inh = emon.Port.CellsAt(se, at + SeInh);
            if (g > 0) {
                mean = TgMean(emon.Port.CellsAt(se, at + SeOwnsz), g);
                bold = TgPm(emon.Port.CellsAt(se, at + SeOwnbd), g);
                skip = 0;
                if ((role == RoTh) || (role == RoTd) || (role == RoLbl) || (role == RoFormula) || (role == RoFigure)) {
                    skip = 1;
                }
                if ((skip == 0) && (inh == 1)) {
                    emon.Port.CellsSet(ss, SsHeads, emon.Port.CellsAt(ss, SsHeads) + 1);
                    if ((mean * 100) >= (body * 108)) {
                        emon.Port.CellsSet(ss, SsHeadsok, emon.Port.CellsAt(ss, SsHeadsok) + 1);
                    } else if ((bold >= 700) && ((mean * 100) >= (body * 95))) {
                        emon.Port.CellsSet(ss, SsHeadsok, emon.Port.CellsAt(ss, SsHeadsok) + 1);
                    }
                }
                if ((skip == 0) && (g <= 300) && ((mean * 100) >= (body * 125))) {
                    emon.Port.CellsSet(ss, SsBig, emon.Port.CellsAt(ss, SsBig) + 1);
                    if (inh == 1) {
                        emon.Port.CellsSet(ss, SsBighead, emon.Port.CellsAt(ss, SsBighead) + 1);
                    }
                }
            }
            if ((role == RoHn) && (emon.Port.CellsAt(se, at + SeSubg) > 0)) {
                lvl = emon.Port.CellsAt(se, at + SeLevel);
                mean = TgMean(emon.Port.CellsAt(se, at + SeSubsz), emon.Port.CellsAt(se, at + SeSubg));
                if ((lvl >= 1) && (lvl <= 6)) {
                    emon.Port.CellsSet(hh, 4096 + (lvl * 2), emon.Port.CellsAt(hh, 4096 + (lvl * 2)) + mean);
                    emon.Port.CellsSet(hh, 4097 + (lvl * 2), emon.Port.CellsAt(hh, 4097 + (lvl * 2)) + 1);
                }
                if (prevl > 0) {
                    emon.Port.CellsSet(ss, SsLvpairs, emon.Port.CellsAt(ss, SsLvpairs) + 1);
                    if (lvl <= (prevl + 1)) {
                        emon.Port.CellsSet(ss, SsLvok, emon.Port.CellsAt(ss, SsLvok) + 1);
                    }
                }
                prevl = lvl;
            }
            r += 1;
        }
        l = 1;
        while (l <= 6) {
            if (emon.Port.CellsAt(hh, 4097 + (l * 2)) > 0) {
                cmean = emon.Port.CellsAt(hh, 4096 + (l * 2)) / emon.Port.CellsAt(hh, 4097 + (l * 2));
                if (pl > 0) {
                    emon.Port.CellsSet(ss, SsLvpairs, emon.Port.CellsAt(ss, SsLvpairs) + 1);
                    if ((pmean * 100) >= (cmean * 97)) {
                        emon.Port.CellsSet(ss, SsLvok, emon.Port.CellsAt(ss, SsLvok) + 1);
                    }
                }
                pl = l;
                pmean = cmean;
            }
            l += 1;
        }
        return 0;
    }
    internal static int TgJArtifacts(emon.Port.Cells ss, emon.Port.Cells sa, emon.Port.Cells gl, emon.Port.Cells mk, emon.Port.Cells pg) {
        // One `sa` row per OUTERMOST artifact span: where its text sits on the page, and whether what it
        // says it is (a header, a footer, pagination, a watermark) agrees: a header lies in the top 12 per cent
        // of the page, a footer in the bottom 12, other furniture in a margin, a watermark is turned, light or
        // large. A span with no text is `unchecked`: a rule or a shading says nothing to verify.
        emon.Port.CellsDrop(sa, 0);
        int nmk = Evidence.MkCount(mk);
        int npg = Pdfdoc.PdPgCount(pg);
        int m = 0;
        int p = 0;
        int nested = 0;
        int row = 0;
        int at = 0;
        int pi = 0;
        int g0 = 0;
        int gn = 0;
        int g = 0;
        int cnt = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int szs = 0;
        int lum = 0;
        int fill = 0;
        int rot = 0;
        int pw = 0;
        int ph = 0;
        int rt = 0;
        int band = 0;
        int verdict = 0;
        int sub = 0;
        int marginal = 0;
        int wm = 0;
        int meansz = 0;
        int meanlum = 0;
        int i = 0;
        while (m < nmk) {
            if (Evidence.MkGet(mk, m, Evidence.MkfKind()) == 1) {
                nested = 0;
                p = Evidence.MkGet(mk, m, Evidence.MkfParent());
                while (p >= 0) {
                    if (Evidence.MkGet(mk, p, Evidence.MkfKind()) == 1) {
                        nested = 1;
                    }
                    p = Evidence.MkGet(mk, p, Evidence.MkfParent());
                }
                if (nested == 0) {
                    pi = Evidence.MkGet(mk, m, Evidence.MkfPage()) - 1;
                    g0 = Evidence.MkGet(mk, m, Evidence.MkfGfirst());
                    gn = Evidence.MkGet(mk, m, Evidence.MkfGcount());
                    cnt = 0;
                    x0 = 0;
                    y0 = 0;
                    x1 = 0;
                    y1 = 0;
                    szs = 0;
                    lum = 0;
                    rot = 0;
                    g = 0;
                    while (g < gn) {
                        if (cnt == 0) {
                            x0 = Evidence.GlGet(gl, g0 + g, Evidence.ChX0());
                            y0 = Evidence.GlGet(gl, g0 + g, Evidence.ChY0());
                            x1 = Evidence.GlGet(gl, g0 + g, Evidence.ChX1());
                            y1 = Evidence.GlGet(gl, g0 + g, Evidence.ChY1());
                            rot = Evidence.GlGet(gl, g0 + g, Evidence.GfRot());
                        } else {
                            x0 = TgMin(x0, Evidence.GlGet(gl, g0 + g, Evidence.ChX0()));
                            y0 = TgMin(y0, Evidence.GlGet(gl, g0 + g, Evidence.ChY0()));
                            x1 = TgMax(x1, Evidence.GlGet(gl, g0 + g, Evidence.ChX1()));
                            y1 = TgMax(y1, Evidence.GlGet(gl, g0 + g, Evidence.ChY1()));
                        }
                        szs += TgMin(TgMax(Evidence.GlGet(gl, g0 + g, Evidence.GfSize()), 0), 6000) / 10;
                        fill = Evidence.GlGet(gl, g0 + g, Evidence.GfFill());
                        if (fill >= 0) {
                            lum += (((((fill / 65536) & 255) * 299) + (((fill / 256) & 255) * 587)) + ((fill & 255) * 114)) / 1000;
                        }
                        cnt += 1;
                        g += 1;
                    }
                    sub = Evidence.MkGet(mk, m, Evidence.MkfArsub());
                    band = 0;
                    verdict = 0;
                    meansz = 0;
                    meanlum = -1;
                    if (cnt > 0) {
                        meansz = TgMean(szs, cnt);
                        meanlum = lum / cnt;
                        pw = 0;
                        ph = 0;
                        if ((pi >= 0) && (pi < npg)) {
                            pw = Pdfdoc.PdPgCrop(pg, pi, 2) - Pdfdoc.PdPgCrop(pg, pi, 0);
                            ph = Pdfdoc.PdPgCrop(pg, pi, 3) - Pdfdoc.PdPgCrop(pg, pi, 1);
                            rt = Pdfdoc.PdPgRotate(pg, pi);
                            if ((rt == 90) || (rt == 270)) {
                                i = pw;
                                pw = ph;
                                ph = i;
                            }
                        }
                        band = 1;
                        if (pw > 0) {
                            if (((y0 + y1) * 100) < (ph * 24)) {
                                band = 2;
                            }
                            if (((y0 + y1) * 100) > (ph * 176)) {
                                band = 3;
                            }
                            if (band == 1) {
                                if ((((x0 + x1) * 100) < (pw * 16)) || (((x0 + x1) * 100) > (pw * 184))) {
                                    band = 4;
                                }
                            }
                        }
                        marginal = 0;
                        if (band > 1) {
                            marginal = 1;
                        }
                        wm = 0;
                        if ((rot != 0) || (meanlum >= 170) || (meansz >= 3600)) {
                            wm = 1;
                        }
                        if (sub == 1) {
                            if (band == 2) {
                                verdict = 1;
                            } else {
                                verdict = 2;
                            }
                        }
                        if (sub == 2) {
                            if (band == 3) {
                                verdict = 1;
                            } else {
                                verdict = 2;
                            }
                        }
                        if (sub == 3) {
                            if (wm == 1) {
                                verdict = 1;
                            } else {
                                verdict = 2;
                            }
                        }
                        if ((sub != 1) && (sub != 2) && (sub != 3)) {
                            if ((marginal == 1) || (wm == 1)) {
                                verdict = 1;
                            } else {
                                verdict = 2;
                            }
                        }
                        if (verdict == 1) {
                            emon.Port.CellsSet(ss, SsArtok, emon.Port.CellsAt(ss, SsArtok) + 1);
                        }
                        if (verdict == 2) {
                            emon.Port.CellsSet(ss, SsArtbad, emon.Port.CellsAt(ss, SsArtbad) + 1);
                        }
                        emon.Port.CellsSet(ss, SsArtglyphs, emon.Port.CellsAt(ss, SsArtglyphs) + cnt);
                    }
                    row = emon.Port.CellsLen(sa) / SaStride;
                    at = row * SaStride;
                    i = 0;
                    while (i < SaStride) {
                        emon.Port.CellsPush(sa, 0);
                        i += 1;
                    }
                    emon.Port.CellsSet(sa, at + 0, m);
                    emon.Port.CellsSet(sa, at + 1, pi);
                    emon.Port.CellsSet(sa, at + 2, Evidence.MkGet(mk, m, Evidence.MkfArtype()));
                    emon.Port.CellsSet(sa, at + 3, sub);
                    emon.Port.CellsSet(sa, at + 4, cnt);
                    emon.Port.CellsSet(sa, at + 5, x0);
                    emon.Port.CellsSet(sa, at + 6, y0);
                    emon.Port.CellsSet(sa, at + 7, x1);
                    emon.Port.CellsSet(sa, at + 8, y1);
                    emon.Port.CellsSet(sa, at + 9, band);
                    emon.Port.CellsSet(sa, at + 10, rot);
                    emon.Port.CellsSet(sa, at + 11, meansz);
                    emon.Port.CellsSet(sa, at + 12, verdict);
                    emon.Port.CellsSet(sa, at + 13, meanlum);
                    emon.Port.CellsSet(ss, SsArts, emon.Port.CellsAt(ss, SsArts) + 1);
                }
            }
            m += 1;
        }
        return 0;
    }
    internal static int TgHv(emon.Port.Cells ss, int v, int w, int gate) {
        // Add one component to the weighted harmonic mean: `SS_WSUM` is the weights' sum, `SS_HSUM` the sum of
        // weight / value (value floored at `TG_FLOOR`, in millionths) and `SS_MINC` the weakest of the components that
        // verify something (`gate` 1: all but the diversity, which is a prior about the document, not a check).
        if (v < 0) {
            return 0;
        }
        if ((gate == 1) && (v < emon.Port.CellsAt(ss, SsMinc))) {
            emon.Port.CellsSet(ss, SsMinc, v);
        }
        emon.Port.CellsSet(ss, SsWsum, emon.Port.CellsAt(ss, SsWsum) + w);
        emon.Port.CellsSet(ss, SsHsum, emon.Port.CellsAt(ss, SsHsum) + ((w * 1000000) / TgMax(v, TgFloor)));
        return 0;
    }
    internal static int TgChance(int agree) {
        // An agreement rate between two orders, corrected for chance: a coin flip agrees half the time, so half
        // is 0 and all is 1000.
        return TgMax(0, (agree * 2) - 1000);
    }
    internal static int TgDiv(int classes) {
        // Role diversity per mille from the number of informative classes in use: none 0 (every block
        // a paragraph says nothing about the document), one 500, two 750, three or more 1000.
        if (classes <= 0) {
            return 0;
        }
        if (classes == 1) {
            return 500;
        }
        if (classes == 2) {
            return 750;
        }
        return 1000;
    }
    internal static int TgJScore(emon.Port.Cells ss) {
        // The components (per mille, -1 when there is nothing to check), their weighted harmonic mean, and that mean
        // scaled by (1000 + the weakest check) / 2000: no tree is better than its weakest check.
        int glyphs = emon.Port.CellsAt(ss, SsGlyphs);
        int v = 0;
        int hp = 0;
        int hn = 0;
        int hdr = -1;
        int score = 0;
        int trust = 0;
        int prior = 0;
        int ua = 0;
        emon.Port.CellsSet(ss, SsWsum, 0);
        emon.Port.CellsSet(ss, SsHsum, 0);
        emon.Port.CellsSet(ss, SsMinc, 1000);
        if (emon.Port.CellsAt(ss, SsPresent) == 0) {
            return 0;
        }
        prior = 300;
        if (emon.Port.CellsAt(ss, SsMarked) == 1) {
            prior = 500;
        }
        if ((emon.Port.CellsAt(ss, SsMarked) == 1) && (emon.Port.CellsAt(ss, SsUapart) >= 1)) {
            prior = 700;
            ua = 1;
        }
        emon.Port.CellsSet(ss, SsPrior, prior);
        if (glyphs == 0) {
            emon.Port.CellsSet(ss, SsStatus, 1);
            return 0;
        }
        emon.Port.CellsSet(ss, SsStatus, 2);
        emon.Port.CellsSet(ss, SsCov, TgPm(emon.Port.CellsAt(ss, SsCovered) + emon.Port.CellsAt(ss, SsArtg), glyphs));
        emon.Port.CellsSet(ss, SsDiv, TgDiv(emon.Port.CellsAt(ss, SsNclasses)));
        if (emon.Port.CellsAt(ss, SsTrans) >= TgMinpairs) {
            emon.Port.CellsSet(ss, SsOrd, TgChance(TgPm(emon.Port.CellsAt(ss, SsTransok), emon.Port.CellsAt(ss, SsTrans))));
        }
        if (emon.Port.CellsAt(ss, SsHeads) > 0) {
            hp = TgPm(emon.Port.CellsAt(ss, SsHeadsok), emon.Port.CellsAt(ss, SsHeads));
            hn += 1;
        }
        if (emon.Port.CellsAt(ss, SsBig) > 0) {
            v = TgPm(emon.Port.CellsAt(ss, SsBighead), emon.Port.CellsAt(ss, SsBig));
            hp += v;
            hn += 1;
        }
        if (hn > 0) {
            hdr = hp / hn;
        }
        emon.Port.CellsSet(ss, SsHdr, hdr);
        if (emon.Port.CellsAt(ss, SsLvpairs) >= TgMinpairs) {
            emon.Port.CellsSet(ss, SsLv, TgChance(TgPm(emon.Port.CellsAt(ss, SsLvok), emon.Port.CellsAt(ss, SsLvpairs))));
        }
        if ((emon.Port.CellsAt(ss, SsArtok) + emon.Port.CellsAt(ss, SsArtbad)) > 0) {
            emon.Port.CellsSet(ss, SsArt, TgPm(emon.Port.CellsAt(ss, SsArtok), emon.Port.CellsAt(ss, SsArtok) + emon.Port.CellsAt(ss, SsArtbad)));
        }
        if (emon.Port.CellsAt(ss, SsNest) > 0) {
            emon.Port.CellsSet(ss, SsNestr, TgPm(emon.Port.CellsAt(ss, SsNestok), emon.Port.CellsAt(ss, SsNest)));
        }
        TgHv(ss, emon.Port.CellsAt(ss, SsCov), 3, 1);
        TgHv(ss, emon.Port.CellsAt(ss, SsDiv), 2, 0);
        TgHv(ss, emon.Port.CellsAt(ss, SsOrd), 2, 1);
        TgHv(ss, emon.Port.CellsAt(ss, SsHdr), 2, 1);
        TgHv(ss, emon.Port.CellsAt(ss, SsLv), 2, 1);
        TgHv(ss, emon.Port.CellsAt(ss, SsArt), 2, 1);
        TgHv(ss, emon.Port.CellsAt(ss, SsNestr), 1, 1);
        if (emon.Port.CellsAt(ss, SsHsum) > 0) {
            score = (emon.Port.CellsAt(ss, SsWsum) * 1000000) / emon.Port.CellsAt(ss, SsHsum);
        }
        score = (score * (1000 + TgMax(0, emon.Port.CellsAt(ss, SsMinc)))) / 2000;
        score = TgMin(score, 1000);
        emon.Port.CellsSet(ss, SsScore, score);
        trust = score;
        if (ua == 1) {
            trust = TgMin(1000, score + (score / 10));
        }
        emon.Port.CellsSet(ss, SsTrust, trust);
        return 0;
    }
    public static int TgJoin(emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells sk, emon.Port.Cells sc, emon.Port.Cells so, emon.Port.Cells sa, emon.Port.Cells gl, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pg, emon.Port.Cells ha, emon.Port.Cells hb, emon.Port.Cells hh) {
        // Join the tree to the text layer and score it, after `tg-read` and the content interpreter
        // (`gl mk fnt` are its glyphs, marked content and fonts; `pg` the page table). `sa` is cleared; `ha hb
        // hh` are scratch. Answers 0, or -1 when the tree is absent or the text layer too large (3,000,000
        // glyphs) for the sums to fit.
        if (emon.Port.CellsAt(ss, SsPresent) == 0) {
            TgJScore(ss);
            return -1;
        }
        if (Evidence.GlCount(gl) > 3000000) {
            return -1;
        }
        TgJMarks(ss, sc, mk, ha, hb);
        TgJGlyphs(ss, sc, gl, mk, fnt, hb, hh);
        TgJSub(ss, se, sc, so);
        TgJOrder(ss, sc, gl);
        TgJClasses(ss, se);
        TgJTables(sk, se);
        TgJLists(sk, se, sc, gl);
        TgJHeadings(ss, se, hh);
        TgJArtifacts(ss, sa, gl, mk, pg);
        TgJScore(ss);
        return 0;
    }
    internal static int TgDumpRun(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells c, int at) {
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(c, at), emon.Port.CellsAt(c, at + 1));
        return 0;
    }
    internal static int TgDumpElem(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells se, emon.Port.Cells sk, int row) {
        int at = row * SeStride;
        int k = 0;
        int kn = 0;
        int j = 0;
        int v = 0;
        emon.Port.TextAscii(t, "{\"obj\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeObj));
        emon.Port.TextAscii(t, ",\"parent\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeParent));
        emon.Port.TextAscii(t, ",\"depth\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeDepth));
        emon.Port.TextAscii(t, ",\"s\":");
        TgDumpRun(t, txt, se, at + SeRoles);
        emon.Port.TextAscii(t, ",\"role\":");
        if (emon.Port.CellsAt(se, at + SeRole) == 0) {
            emon.Port.TextAscii(t, "null");
        } else {
            emon.Port.TextAscii(t, "\"");
            if (emon.Port.CellsAt(se, at + SeRole) == RoHn) {
                emon.Port.TextAscii(t, "H");
                emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeLevel));
            } else {
                Pdfsnames.SrEmitName(t, emon.Port.CellsAt(se, at + SeRole));
            }
            emon.Port.TextAscii(t, "\"");
        }
        emon.Port.TextAscii(t, ",\"how\":\"");
        TgHowEmitName(t, emon.Port.CellsAt(se, at + SeHow));
        emon.Port.TextAscii(t, "\"");
        if (emon.Port.CellsAt(se, at + SeHlev) > 0) {
            emon.Port.TextAscii(t, ",\"hlevel\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeHlev));
        }
        if (emon.Port.CellsAt(se, at + SePg) >= 0) {
            emon.Port.TextAscii(t, ",\"page\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SePg));
        }
        emon.Port.TextAscii(t, ",\"kids\":[");
        k = emon.Port.CellsAt(se, at + SeKfirst);
        kn = emon.Port.CellsAt(se, at + SeKcount);
        j = 0;
        while ((k >= 0) && (j < kn)) {
            if (j > 0) {
                emon.Port.TextAscii(t, ",");
            }
            v = (k + j) * SkStride;
            emon.Port.TextAscii(t, "[\"");
            TgKindEmitName(t, emon.Port.CellsAt(sk, v));
            emon.Port.TextAscii(t, "\",");
            emon.Port.TextI32(t, emon.Port.CellsAt(sk, v + 1));
            emon.Port.TextAscii(t, "]");
            j += 1;
        }
        emon.Port.TextAscii(t, "]");
        if (emon.Port.CellsAt(se, at + SeAlt) >= 0) {
            emon.Port.TextAscii(t, ",\"alt\":");
            TgDumpRun(t, txt, se, at + SeAlt);
        }
        if (emon.Port.CellsAt(se, at + SeAct) >= 0) {
            emon.Port.TextAscii(t, ",\"actualText\":");
            TgDumpRun(t, txt, se, at + SeAct);
        }
        if (emon.Port.CellsAt(se, at + SeExp) >= 0) {
            emon.Port.TextAscii(t, ",\"expansion\":");
            TgDumpRun(t, txt, se, at + SeExp);
        }
        if (emon.Port.CellsAt(se, at + SeLang) >= 0) {
            emon.Port.TextAscii(t, ",\"lang\":");
            TgDumpRun(t, txt, se, at + SeLang);
        }
        if (emon.Port.CellsAt(se, at + SeLangsrc) != -1) {
            emon.Port.TextAscii(t, ",\"langFrom\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeLangsrc));
        }
        if (emon.Port.CellsAt(se, at + SeId) >= 0) {
            emon.Port.TextAscii(t, ",\"id\":");
            TgDumpRun(t, txt, se, at + SeId);
        }
        if (emon.Port.CellsAt(se, at + SeTitle) >= 0) {
            emon.Port.TextAscii(t, ",\"title\":");
            TgDumpRun(t, txt, se, at + SeTitle);
        }
        if (emon.Port.CellsAt(se, at + SeScope) > 0) {
            emon.Port.TextAscii(t, ",\"scope\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeScope));
        }
        if (emon.Port.CellsAt(se, at + SeRowspan) >= 0) {
            emon.Port.TextAscii(t, ",\"rowSpan\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeRowspan));
        }
        if (emon.Port.CellsAt(se, at + SeColspan) >= 0) {
            emon.Port.TextAscii(t, ",\"colSpan\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeColspan));
        }
        if (emon.Port.CellsAt(se, at + SeHeads) >= 0) {
            emon.Port.TextAscii(t, ",\"headers\":");
            TgDumpRun(t, txt, se, at + SeHeads);
        }
        if (emon.Port.CellsAt(se, at + SeSumm) >= 0) {
            emon.Port.TextAscii(t, ",\"summary\":");
            TgDumpRun(t, txt, se, at + SeSumm);
        }
        if (emon.Port.CellsAt(se, at + SeListnum) > 0) {
            emon.Port.TextAscii(t, ",\"listNumbering\":\"");
            TgListnumEmitName(t, emon.Port.CellsAt(se, at + SeListnum));
            emon.Port.TextAscii(t, "\"");
        }
        emon.Port.TextAscii(t, ",\"bits\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeBits));
        emon.Port.TextAscii(t, ",\"size\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeSize));
        if (emon.Port.CellsAt(se, at + SeSubc) > 0) {
            emon.Port.TextAscii(t, ",\"content\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeSubc));
        }
        if (emon.Port.CellsAt(se, at + SeSubg) > 0) {
            emon.Port.TextAscii(t, ",\"glyphs\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeSubg));
            emon.Port.TextAscii(t, ",\"ownGlyphs\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeOwng));
            emon.Port.TextAscii(t, ",\"meanSize\":");
            Pdfx.PxJsonCp(t, TgMean(emon.Port.CellsAt(se, at + SeSubsz), emon.Port.CellsAt(se, at + SeSubg)));
            emon.Port.TextAscii(t, ",\"bold\":");
            emon.Port.TextI32(t, TgPm(emon.Port.CellsAt(se, at + SeSubbd), emon.Port.CellsAt(se, at + SeSubg)));
            emon.Port.TextAscii(t, ",\"firstPage\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeFpg));
            emon.Port.TextAscii(t, ",\"box\":");
            Pdfx.PxJsonBox(t, se, at + SeBx0);
        }
        if (emon.Port.CellsAt(se, at + SeTrows) > 0) {
            emon.Port.TextAscii(t, ",\"rows\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeTrows));
            emon.Port.TextAscii(t, ",\"cols\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeTcols));
            emon.Port.TextAscii(t, ",\"regular\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeTreg));
        }
        if (emon.Port.CellsAt(se, at + SeLitems) > 0) {
            emon.Port.TextAscii(t, ",\"items\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeLitems));
            emon.Port.TextAscii(t, ",\"labelled\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeLlbl));
            emon.Port.TextAscii(t, ",\"labelsAgree\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeLok));
            emon.Port.TextAscii(t, ",\"labelsDiffer\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeLbad));
            emon.Port.TextAscii(t, ",\"labelKind\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(se, at + SeLkind));
        }
        emon.Port.TextAscii(t, "}");
        return 0;
    }
    internal static int TgDumpContent(System.Text.StringBuilder t, emon.Port.Cells sc, int row) {
        int at = row * ScStride;
        emon.Port.TextAscii(t, "{\"elem\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScElem));
        emon.Port.TextAscii(t, ",\"kind\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScKind));
        emon.Port.TextAscii(t, ",\"page\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScPage));
        emon.Port.TextAscii(t, ",\"mcid\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScMcid));
        emon.Port.TextAscii(t, ",\"stm\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScStm));
        emon.Port.TextAscii(t, ",\"mark\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScMark));
        emon.Port.TextAscii(t, ",\"glyphs\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScGcount));
        emon.Port.TextAscii(t, ",\"owned\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScOwng));
        emon.Port.TextAscii(t, ",\"flags\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sc, at + ScFlags));
        emon.Port.TextAscii(t, "}");
        return 0;
    }
    internal static int TgDumpKv(System.Text.StringBuilder t, emon.Port.Cells ss, int cell) {
        emon.Port.TextI32(t, emon.Port.CellsAt(ss, cell));
        return 0;
    }
    public static int TgDump(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells ss, emon.Port.Cells se, emon.Port.Cells sk, emon.Port.Cells sc, emon.Port.Cells so, emon.Port.Cells sa) {
        // The tree, the join and the score as one canonical JSON object: `{"tree":{..},"score":{..},
        // "elements":[..],"content":[..],"objr":[..],"artifacts":[..]}`, rows in arena order.
        // Not a public contract (the Model says what it needs of these): what the laws and the oracle compare.
        int nse = emon.Port.CellsLen(se) / SeStride;
        int nsc = emon.Port.CellsLen(sc) / ScStride;
        int nso = emon.Port.CellsLen(so) / SoStride;
        int nsa = emon.Port.CellsLen(sa) / SaStride;
        int i = 0;
        int at = 0;
        emon.Port.TextAscii(t, "{\"tree\":{\"present\":");
        TgDumpKv(t, ss, SsPresent);
        emon.Port.TextAscii(t, ",\"marked\":");
        TgDumpKv(t, ss, SsMarked);
        emon.Port.TextAscii(t, ",\"suspects\":");
        TgDumpKv(t, ss, SsSuspects);
        emon.Port.TextAscii(t, ",\"userProperties\":");
        TgDumpKv(t, ss, SsUserprops);
        emon.Port.TextAscii(t, ",\"pdfuaPart\":");
        TgDumpKv(t, ss, SsUapart);
        emon.Port.TextAscii(t, ",\"pdfuaRev\":");
        TgDumpKv(t, ss, SsUarev);
        emon.Port.TextAscii(t, ",\"lang\":");
        TgDumpRun(t, txt, ss, SsLang);
        emon.Port.TextAscii(t, ",\"elements\":");
        TgDumpKv(t, ss, SsElems);
        emon.Port.TextAscii(t, ",\"content\":");
        TgDumpKv(t, ss, SsContent);
        emon.Port.TextAscii(t, ",\"objr\":");
        TgDumpKv(t, ss, SsObjrs);
        emon.Port.TextAscii(t, ",\"depth\":");
        TgDumpKv(t, ss, SsMaxdepth);
        emon.Port.TextAscii(t, ",\"limits\":");
        TgDumpKv(t, ss, SsLimits);
        emon.Port.TextAscii(t, ",\"roleMap\":");
        TgDumpKv(t, ss, SsRolemapn);
        emon.Port.TextAscii(t, ",\"classMap\":");
        TgDumpKv(t, ss, SsClassmapn);
        emon.Port.TextAscii(t, ",\"customRoles\":");
        TgDumpKv(t, ss, SsCustom);
        emon.Port.TextAscii(t, ",\"unresolvedRoles\":");
        TgDumpKv(t, ss, SsUnresolved);
        emon.Port.TextAscii(t, ",\"shadowedRoles\":");
        TgDumpKv(t, ss, SsShadowed);
        emon.Port.TextAscii(t, ",\"parentTree\":[");
        TgDumpKv(t, ss, SsPtkeys);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsPtok);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsPtbad);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsPtnone);
        emon.Port.TextAscii(t, "],\"tables\":");
        TgDumpKv(t, ss, SsTables);
        emon.Port.TextAscii(t, ",\"lists\":");
        TgDumpKv(t, ss, SsLists);
        emon.Port.TextAscii(t, "},\"score\":{\"status\":");
        TgDumpKv(t, ss, SsStatus);
        emon.Port.TextAscii(t, ",\"marks\":");
        TgDumpKv(t, ss, SsMarks);
        emon.Port.TextAscii(t, ",\"joined\":");
        TgDumpKv(t, ss, SsJoined);
        emon.Port.TextAscii(t, ",\"unjoined\":");
        TgDumpKv(t, ss, SsUnjoined);
        emon.Port.TextAscii(t, ",\"duplicates\":");
        TgDumpKv(t, ss, SsDups);
        emon.Port.TextAscii(t, ",\"glyphs\":[");
        TgDumpKv(t, ss, SsGlyphs);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsCovered);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsArtg);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsUntagged);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsUnclaimed);
        emon.Port.TextAscii(t, "],\"order\":[");
        TgDumpKv(t, ss, SsTrans);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsTransok);
        emon.Port.TextAscii(t, "],\"classes\":");
        TgDumpKv(t, ss, SsClasses);
        emon.Port.TextAscii(t, ",\"headings\":[");
        TgDumpKv(t, ss, SsHeads);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsHeadsok);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsBig);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsBighead);
        emon.Port.TextAscii(t, "],\"bodySize\":");
        Pdfx.PxJsonCp(t, emon.Port.CellsAt(ss, SsBody));
        emon.Port.TextAscii(t, ",\"levels\":[");
        TgDumpKv(t, ss, SsLvpairs);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsLvok);
        emon.Port.TextAscii(t, "],\"nesting\":[");
        TgDumpKv(t, ss, SsNest);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsNestok);
        emon.Port.TextAscii(t, "],\"artifacts\":[");
        TgDumpKv(t, ss, SsArts);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsArtok);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsArtbad);
        emon.Port.TextAscii(t, ",");
        TgDumpKv(t, ss, SsArtglyphs);
        emon.Port.TextAscii(t, "],\"coverage\":");
        TgDumpKv(t, ss, SsCov);
        emon.Port.TextAscii(t, ",\"diversity\":");
        TgDumpKv(t, ss, SsDiv);
        emon.Port.TextAscii(t, ",\"readingOrder\":");
        TgDumpKv(t, ss, SsOrd);
        emon.Port.TextAscii(t, ",\"headingFit\":");
        TgDumpKv(t, ss, SsHdr);
        emon.Port.TextAscii(t, ",\"levelFit\":");
        TgDumpKv(t, ss, SsLv);
        emon.Port.TextAscii(t, ",\"artifactFit\":");
        TgDumpKv(t, ss, SsArt);
        emon.Port.TextAscii(t, ",\"nestingFit\":");
        TgDumpKv(t, ss, SsNestr);
        emon.Port.TextAscii(t, ",\"score\":");
        TgDumpKv(t, ss, SsScore);
        emon.Port.TextAscii(t, ",\"prior\":");
        TgDumpKv(t, ss, SsPrior);
        emon.Port.TextAscii(t, ",\"trust\":");
        TgDumpKv(t, ss, SsTrust);
        emon.Port.TextAscii(t, "},\"elements\":[");
        while (i < nse) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            TgDumpElem(t, txt, se, sk, i);
            i += 1;
        }
        emon.Port.TextAscii(t, "],\"content\":[");
        i = 0;
        while (i < nsc) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            TgDumpContent(t, sc, i);
            i += 1;
        }
        emon.Port.TextAscii(t, "],\"objr\":[");
        i = 0;
        while (i < nso) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            at = i * SoStride;
            emon.Port.TextAscii(t, "[");
            emon.Port.TextI32(t, emon.Port.CellsAt(so, at));
            emon.Port.TextAscii(t, ",");
            emon.Port.TextI32(t, emon.Port.CellsAt(so, at + 1));
            emon.Port.TextAscii(t, ",");
            emon.Port.TextI32(t, emon.Port.CellsAt(so, at + 2));
            emon.Port.TextAscii(t, ",\"");
            TgObjrEmitName(t, emon.Port.CellsAt(so, at + 3));
            emon.Port.TextAscii(t, "\",");
            emon.Port.TextI32(t, emon.Port.CellsAt(so, at + 4));
            emon.Port.TextAscii(t, "]");
            i += 1;
        }
        emon.Port.TextAscii(t, "],\"artifactSpans\":[");
        i = 0;
        while (i < nsa) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            at = i * SaStride;
            emon.Port.TextAscii(t, "{\"mark\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(sa, at));
            emon.Port.TextAscii(t, ",\"page\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(sa, at + 1));
            emon.Port.TextAscii(t, ",\"type\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(sa, at + 2));
            emon.Port.TextAscii(t, ",\"subtype\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(sa, at + 3));
            emon.Port.TextAscii(t, ",\"glyphs\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(sa, at + 4));
            if (emon.Port.CellsAt(sa, at + 4) > 0) {
                emon.Port.TextAscii(t, ",\"box\":");
                Pdfx.PxJsonBox(t, sa, at + 5);
                emon.Port.TextAscii(t, ",\"rot\":");
                emon.Port.TextI32(t, emon.Port.CellsAt(sa, at + 10));
                emon.Port.TextAscii(t, ",\"size\":");
                Pdfx.PxJsonCp(t, emon.Port.CellsAt(sa, at + 11));
                emon.Port.TextAscii(t, ",\"luminance\":");
                emon.Port.TextI32(t, emon.Port.CellsAt(sa, at + 13));
            }
            emon.Port.TextAscii(t, ",\"where\":\"");
            TgBandEmitName(t, emon.Port.CellsAt(sa, at + 9));
            emon.Port.TextAscii(t, "\",\"verdict\":\"");
            TgVerdictEmitName(t, emon.Port.CellsAt(sa, at + 12));
            emon.Port.TextAscii(t, "\"}");
            i += 1;
        }
        emon.Port.TextAscii(t, "]}");
        return 0;
    }
    public static int TgTrust(emon.Port.Cells ss) {
        // The tree's TRUST (D150): the informativeness score, raised a tenth by a PDF/UA claim; 0 when there is no tree, no
        // text to check, or `tg-join` has not run. What other stages weigh the tree's word by (D034, D076).
        if (emon.Port.CellsLen(ss) <= SsTrust) {
            return 0;
        }
        return emon.Port.CellsAt(ss, SsTrust);
    }
}
